'use strict';
const {CIRCUIT_DEVICES,isNBar,HOLES,TYPES,NETWORK,BUSBARS,BUSBAR_DEVICES,LIMITS,dims,validDims,ports,getPort,fits,canConnect,validate,parse,exampleName}=DIN;
const {analyze,underBusbar}=DINTopology;
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''), colors={L:'#7b523c',L1:'#7b523c',L2:'#303e46',L3:'#d23a2f',N:'#2f8cc6',PE:'#61a33a',PEN:'#2f7f6a'};
const fresh=(name='Rozdzielnia domu',rows=4,modules=18)=>({version:1,name,rows,modules,network:{system:'',supply:'',mainFuse:''},components:[],wires:[],busbars:[],circuits:[]});
function demo(){let s=fresh();const add=(type,label,row,slot)=>s.components.push({id:uid(),type,label,row,slot,rating:TYPES[type].rating,on:true});add('MAIN','Q0',0,0);add('SPD','SPD1',0,5);add('PE','PE1',0,14);add('RCD','RCD1',1,0);add('MCB','F1',1,5);add('MCB','F2',1,7);add('MCB','F3',1,9);add('N','N1',1,14);add('RCBO','F4',2,0);s.circuits=['Oświetlenie parteru','Gniazda salonu','Gniazda kuchni','Lodówka'].map((name,i)=>({id:uid(),name,device:s.components[[4,5,6,8][i]].id,power:[300,1500,2200,250][i],cable:i?'3 × 2,5':'3 × 1,5'}));s.components[4].rating='B10';return s;}
let state=demo(),selected=null,pending=null,mode='select',showWires=true,checked=false,history=[],future=[],zoom=1;
// First visit on a narrow screen starts with the board fitted to the width.
const firstVisitZoom=(()=>{try{return localStorage.getItem('din-zoom')===null}catch(e){return false}})();
try{const z=Number(localStorage.getItem('din-zoom'));if(z>=.4&&z<=2)zoom=z}catch(e){}
// Projects live in localStorage: an index plus one key per project. The single-project key of older versions is migrated once.
const STORE={index:'din-projects',current:'din-current',legacy:'din-studio-v1',key:id=>'din-project-'+id},MAX_PROJECTS=50;
let projectId=null,savedAt=null;
const readIndex=()=>{try{const v=JSON.parse(localStorage.getItem(STORE.index)||'[]');return Array.isArray(v)?v.filter(p=>p&&typeof p.id==='string'&&/^[a-zA-Z0-9_-]{1,80}$/.test(p.id)):[]}catch(e){return[]}};
const writeIndex=list=>localStorage.setItem(STORE.index,JSON.stringify(list));
function loadProject(id){try{const raw=localStorage.getItem(STORE.key(id));return raw?parse(JSON.parse(raw)):null}catch(e){console.warn('Nie odtworzono projektu',e.message);return null}}
try{let list=readIndex();if(!list.length){const legacy=localStorage.getItem(STORE.legacy);let first=state;if(legacy){try{first=parse(JSON.parse(legacy))}catch(e){}}const id=uid();localStorage.setItem(STORE.key(id),JSON.stringify(first));list=[{id,name:first.name,updated:Date.now()}];writeIndex(list);localStorage.setItem(STORE.current,id)}
 const want=localStorage.getItem(STORE.current),pick=list.find(p=>p.id===want)||list[0],loaded=loadProject(pick.id);projectId=pick.id;if(loaded)state=loaded;}catch(e){console.warn('Zapis lokalny niedostępny',e.message)}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3000)}
function saveStatus(t,bad){const el=$('saveStatus');if(el){el.textContent=t;el.classList.toggle('bad',!!bad)}}
function persist(){try{if(!projectId)projectId=uid();localStorage.setItem(STORE.key(projectId),JSON.stringify(state));const list=readIndex().filter(p=>p.id!==projectId);list.unshift({id:projectId,name:state.name,updated:Date.now()});writeIndex(list);localStorage.setItem(STORE.current,projectId);savedAt=new Date();saveStatus('Zapisano '+savedAt.toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'}));return true}catch(e){saveStatus('Nie zapisano – wyeksportuj JSON',true);toast('Zapis lokalny niedostępny (brak miejsca lub tryb prywatny). Wyeksportuj JSON.');return false}}
function openProjectState(id,next){projectId=id;state=next;history=[];future=[];selected=null;pending=null;checked=false;persist();render()}
function startProject(next){if(readIndex().length>=MAX_PROJECTS){toast(`Maksymalnie ${MAX_PROJECTS} projektów. Usuń stary projekt na liście.`);return false}openProjectState(uid(),next);return true}
function change(fn){history.push(JSON.stringify(state));if(history.length>80)history.shift();future=[];fn();persist();render()}
function restore(from,to){if(!from.length)return;to.push(JSON.stringify(state));state=JSON.parse(from.pop());selected=null;pending=null;persist();render()}
function hint(t){$('hint').textContent=t|| (pending?'Wybierz drugi zacisk. Esc anuluje połączenie.':mode==='wire'?'Kliknij pierwszy i drugi zacisk, aby dodać przewód. Parametry zmienisz w panelu po prawej.':'Przeciągnij aparat z katalogu. Kliknij element, aby edytować jego parametry.')}
function setMode(m){mode=m;pending=null;$('selectMode').classList.toggle('active',m==='select');$('wireMode').classList.toggle('active',m==='wire');render()}
$('catalog').innerHTML=Object.entries(TYPES).filter(([,t])=>t.catalog!==false).map(([key,t])=>`<button class="catalog-item" draggable="false" data-type="${key}" title="${esc(t.name)}${t.example?' · przykład: '+esc(exampleName(key)):''}"><span class="mini-device"></span><span><strong>${t.short}</strong><small>${t.name}</small><small>${t.width} mod.</small>${t.example?`<small class="example">np. ${esc(t.example.series+' '+t.example.name)}</small>`:''}</span></button>`).join('');
$('catalog').addEventListener('click',e=>{if(Date.now()<suppressClickUntil)return;const el=e.target.closest('[data-type]');if(!el)return;const c=makeComponent(el.dataset.type);for(let row=0;row<dims(state).rows;row++)for(let slot=0;slot<dims(state).modules;slot++)if(fits(state,c,row,slot)){change(()=>{c.row=row;c.slot=slot;state.components.push(c);selected={kind:'device',id:c.id}});return}toast('Brak miejsca na ten aparat.')});

// Pointer dragging works with mouse, pen and touch, including browsers without native HTML drag.
let pointerDrag=null, suppressClickUntil=0;
function beginPointerDrag(e,source){
 if(e.button!==0)return;
 const target=e.target.closest(source==='palette'?'[data-type]':'.device');
 if(!target||(source==='device'&&(mode!=='select'||e.target.closest('button'))))return;
 const box=target.getBoundingClientRect();
 pointerDrag={pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,source,
  id:source==='device'?target.dataset.id:null,type:target.dataset.type,
  offsetX:source==='device'?e.clientX-box.left:20,
  offsetY:source==='device'?e.clientY-box.top:49,moved:false,ghost:null};
 target.setPointerCapture(e.pointerId);
}
$('catalog').addEventListener('pointerdown',e=>beginPointerDrag(e,'palette'));
$('components').addEventListener('pointerdown',e=>beginPointerDrag(e,'device'));
document.addEventListener('pointermove',e=>{
 const d=pointerDrag;if(!d||d.pointerId!==e.pointerId)return;
 if(!d.moved&&Math.hypot(e.clientX-d.startX,e.clientY-d.startY)<5)return;
 e.preventDefault();
 if(!d.moved){d.moved=true;d.ghost=document.createElement('div');d.ghost.className='drag-ghost';d.ghost.textContent=d.id?state.components.find(c=>c.id===d.id).label:TYPES[d.type].short;d.ghost.style.width=(TYPES[d.type].width*40-4)*zoom+'px';d.ghost.style.height=98*zoom+'px';document.body.appendChild(d.ghost);$('board').classList.add('drag-active');}
 d.ghost.style.left=(e.clientX-d.offsetX)+'px';d.ghost.style.top=(e.clientY-d.offsetY)+'px';
},{passive:false});
function finishPointerDrag(e,cancel){
 const d=pointerDrag;if(!d||d.pointerId!==e.pointerId)return;pointerDrag=null;d.ghost?.remove();$('board').classList.remove('drag-active');
 if(!d.moved)return;suppressClickUntil=Date.now()+400;
 if(cancel)return;e.preventDefault();
 const b=$('board').getBoundingClientRect();
 // b is the zoomed on-screen rectangle; board coordinates are unzoomed.
 const row=Math.round(((e.clientY-d.offsetY-b.top)/zoom-67)/137),slot=Math.round(((e.clientX-d.offsetX-b.left)/zoom-25)/40);
 const c=d.id?state.components.find(c=>c.id===d.id):makeComponent(d.type);
 if(!c||e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom||!fits(state,c,row,slot)){toast('To miejsce jest zajęte lub poza szyną.');return;}
 change(()=>{c.row=row;c.slot=slot;if(!d.id)state.components.push(c);selected={kind:'device',id:c.id}});
}
document.addEventListener('pointerup',e=>finishPointerDrag(e,false));
document.addEventListener('pointercancel',e=>finishPointerDrag(e,true));

function makeComponent(type){const pre=t=>TYPES[t].prefix||TYPES[t].short,n=state.components.filter(c=>pre(c.type)===pre(type)).length+1;return{id:uid(),type,label:pre(type)+n,row:0,slot:0,rating:TYPES[type].rating,on:true}}
$('components').addEventListener('click',e=>{if(Date.now()<suppressClickUntil)return;const el=e.target.closest('.device');if(!el)return;const id=el.dataset.id,term=e.target.closest('.terminal');if(term){connect({device:id,port:term.dataset.port});return}if(e.target.closest('.lever')){change(()=>{const c=state.components.find(c=>c.id===id);c.on=!c.on;selected={kind:'device',id}});return}selected={kind:'device',id};render()});
function connect(end){if(!pending){pending=end;hint();renderBoard();return}if(pending.device===end.device&&pending.port===end.port){pending=null;render();return}const error=canConnect(state,pending,end);if(error){toast(error);return}const a={...pending},role=getPort(state,a).role;change(()=>{const w={id:uid(),a,b:end,role,gauge:2.5};state.wires.push(w);selected={kind:'wire',id:w.id};pending=null});}
function coord(end){const c=state.components.find(c=>c.id===end.device),p=getPort(state,end);return{x:25+c.slot*40+((p.i+.5)/p.count)*(TYPES[c.type].width*40-4),y:67+c.row*137+(p.side==='t'?9:90)}}
function renderBoard(){
const {rows,modules}=dims(state),board=$('board');board.style.width=modules*40+52+'px';board.style.height=rows*137+80+'px';board.style.zoom=zoom;
$('boardSize').textContent=`RG · ${rows} ${plural(rows,'RZĄD','RZĘDY','RZĘDÓW')} × ${modules} ${plural(modules,'MODUŁ','MODUŁY','MODUŁÓW')}`;
$('rails').innerHTML=Array.from({length:rows},(_,i)=>`<div class="rail" style="top:${58+i*137}px;width:${modules*40}px"><span class="rail-label">RZĄD ${String(i+1).padStart(2,'0')}<button class="railbtn" data-rail="${i}" title="Usuń szynę ${i+1}" aria-label="Usuń szynę ${i+1}" ${rows<=1?'disabled':''}>×</button></span><div class="slotnums">${Array.from({length:modules},(_,j)=>`<span>${j+1}</span>`).join('')}</div></div>`).join('');
$('components').innerHTML=state.components.map(c=>{const t=TYPES[c.type],lever=!(TYPES[c.type].bar||c.type==='SPD'),ex=exampleName(c.type);return `<div class="device ${selected?.kind==='device'&&selected.id===c.id?'selected':''}" data-id="${c.id}" data-type="${c.type}" data-w="${t.width}" draggable="false" style="left:${25+c.slot*40}px;top:${67+c.row*137}px;width:${t.width*40-4}px" title="${esc(c.label)} · ${esc(t.name)}${ex?' · przykład typu (poglądowo): '+esc(ex):''}"><span class="devlabel">${esc(c.label)}</span><span class="devrating">${esc(c.rating)}</span>${lever?`<button class="lever ${c.on?'':'off'}" title="${c.on?'Wyłącz':'Włącz'} aparat w modelu" aria-label="${c.on?'Wyłącz':'Włącz'} ${esc(c.label)}"></button>`:''}${['RCD','RCBO'].includes(c.type)?'<span class="testbtn" aria-hidden="true">T</span>':''}${c.type==='SPD'?`<span class="cartridges" aria-hidden="true">${t.poles.map(()=>'<i></i>').join('')}</span>`:''}${['N','PE','GSU'].includes(c.type)||TYPES[c.type].family?'<span class="busbar" aria-hidden="true"></span>':''}<span class="devtype">${lever?`<i class="st ${c.on?'on':'off'}">${c.on?'I':'O'}</i>`:''}${t.short}</span>${ports(c).map(p=>`<button class="terminal ${p.side==='t'?'top':'bottom'} ${pending?.device===c.id&&pending.port===p.key?'pending':''}" data-port="${p.key}" style="left:${(p.i+.5)/p.count*100}%" title="${esc(c.label)}: ${p.side==='t'?'góra':'dół'} ${p.role} (${p.i+1})" aria-label="Zacisk ${esc(c.label)} ${p.key} ${p.role}"><span>${p.role}</span></button>`).join('')}</div>`}).join('');
labelCircuits();$('wires').style.display=showWires?'block':'none';$('wires').innerHTML=state.wires.map((w,i)=>{const a=coord(w.a),b=coord(w.b),mid=(a.y+b.y)/2+(i%4)*6;const d=`M ${a.x} ${a.y} V ${mid} H ${b.x} V ${b.y}`;return `<path class="wire-hit" data-wire="${w.id}" d="${d}"/><path class="wire ${selected?.kind==='wire'&&selected.id===w.id?'selected':''}" data-wire="${w.id}" d="${d}" stroke="${colors[w.role]}" ${w.role==='PE'?'stroke-dasharray="9 3"':w.role==='PEN'?'stroke-dasharray="3 2"':''}/>`}).join('');
}
// Wires are drawn above devices, so their wide hit area covers the terminal they end on; a terminal under the pointer wins.
$('wires').addEventListener('click',e=>{const term=document.elementsFromPoint(e.clientX,e.clientY).find(el=>el.classList?.contains('terminal'));if(term){const d=term.closest('.device');if(d){connect({device:d.dataset.id,port:term.dataset.port});return}}const id=e.target.dataset.wire;if(id){selected={kind:'wire',id};render()}});
function renderInspector(){if(selected?.kind==='busbar'){renderBusbarInspector();return}const c=selected?.kind==='device'&&state.components.find(c=>c.id===selected.id),w=selected?.kind==='wire'&&state.wires.find(w=>w.id===selected.id);if(c){$('inspector').innerHTML=`<h2>${TYPES[c.type].name}</h2><div class="kv"><span>Typ / szerokość</span><b>${TYPES[c.type].short} / ${TYPES[c.type].width} mod.</b></div><label class="field">Oznaczenie<input id="editLabel" maxlength="60" value="${esc(c.label)}"></label><label class="field">Opis parametrów (bez obliczeń)<input id="editRating" maxlength="100" value="${esc(c.rating)}"></label><div class="kv"><span>Położenie</span><b>Rząd ${c.row+1} · moduł ${c.slot+1}</b></div><label class="field">Rząd<select id="editRow">${Array.from({length:dims(state).rows},(_,r)=>r).map(r=>`<option value="${r}" ${c.row===r?'selected':''}>Rząd ${r+1}</option>`).join('')}</select></label><label class="field">Pierwszy moduł<input id="editSlot" type="number" min="1" max="${dims(state).modules}"value="${c.slot+1}"></label><button class="delete" id="deleteSelected">Usuń aparat i jego przewody</button>`;$('editLabel').onchange=e=>change(()=>c.label=e.target.value.trim()||TYPES[c.type].short);$('editRating').onchange=e=>change(()=>c.rating=e.target.value);const move=()=>{const row=+$('editRow').value,slot=+$('editSlot').value-1;if(!fits(state,c,row,slot)){toast('To miejsce nie jest dostępne.');renderInspector();return}change(()=>{c.row=row;c.slot=slot})};$('editRow').onchange=move;$('editSlot').onchange=move;if(BUSBAR_DEVICES.includes(c.type))appendBusbarForm(c);if(TYPES[c.type].family||TYPES[c.type].holes)appendSizeForm(c);
}else if(w){const label=e=>state.components.find(c=>c.id===e.device).label+' / '+getPort(state,e).role;$('inspector').innerHTML=`<h2>Połączenie przewodem</h2><div class="kv"><span>Od</span><b>${esc(label(w.a))}</b></div><div class="kv"><span>Do</span><b>${esc(label(w.b))}</b></div><label class="field">Funkcja i kolor żyły<select id="wireRole">${Object.keys(colors).map(r=>`<option ${w.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label class="field">Przekrój [mm²]<select id="wireGauge">${[1.5,2.5,4,6,10,16].map(n=>`<option value="${n}" ${w.gauge===n?'selected':''}>${n}</option>`).join('')}</select></label><p class="muted" style="font-size:11px">Przekrój jest zapisanym parametrem. Prototyp nie oblicza jego obciążalności.</p><button class="delete" id="deleteSelected">Usuń przewód</button>`;$('wireRole').onchange=e=>change(()=>w.role=e.target.value);$('wireGauge').onchange=e=>change(()=>w.gauge=+e.target.value);
}else{$('inspector').innerHTML=`<div class="selection-empty"><div class="largeicon">⌖</div><h2>Przestrzeń do projektowania</h2><p>Zaznacz aparat lub przewód, aby zobaczyć i zmienić jego parametry.</p></div><div class="kv"><span>Aparaty</span><b>${state.components.length}</b></div><div class="kv"><span>Połączenia</span><b>${state.wires.length}</b></div><div class="kv"><span>Obudowa</span><b>${dims(state).rows} × ${dims(state).modules} mod.</b></div><div class="kv"><span>Zapis</span><b>W tej przeglądarce</b></div><button id="resizeInspector">Zmień rozmiar obudowy</button><section class="netform"><h3>Parametry sieci</h3><p class="muted">Puste pole oznacza brak danych – kontrola zgłosi to jawnie zamiast zgadywać.</p><label class="field">Układ sieci<select id="netSystem">${NETWORK.system.map(v=>`<option value="${v}" ${(state.network?.system||'')===v?'selected':''}>${v||'Nieznany'}</option>`).join('')}</select></label><label class="field">Zasilanie<select id="netSupply">${NETWORK.supply.map(v=>`<option value="${v}" ${(state.network?.supply||'')===v?'selected':''}>${{'':'Nieznane','3F':'3-fazowe (L1, L2, L3, N)','1F':'1-fazowe (L, N)'}[v]}</option>`).join('')}</select></label><label class="field">Zabezpieczenie przedlicznikowe<input id="netFuse" maxlength="40" placeholder="np. 3 × 25 A gG" value="${esc(state.network?.mainFuse||'')}"></label><p class="muted" style="font-size:10px">Zapisywane do dokumentacji; prototyp nie sprawdza selektywności.</p></section>`;$('resizeInspector').onclick=()=>openSize('resize');const setNet=(k,v)=>change(()=>{state.network={system:'',supply:'',mainFuse:'',...state.network,[k]:v}});$('netSystem').onchange=e=>setNet('system',e.target.value);$('netSupply').onchange=e=>setNet('supply',e.target.value);$('netFuse').onchange=e=>setNet('mainFuse',e.target.value.trim().slice(0,40))}if($('deleteSelected'))$('deleteSelected').onclick=removeSelected;}
function removeSelected(){if(!selected)return;change(()=>{if(selected.kind==='device'){state.components=state.components.filter(c=>c.id!==selected.id);state.wires=state.wires.filter(w=>w.a.device!==selected.id&&w.b.device!==selected.id);state.circuits.forEach(c=>{if(c.device===selected.id)c.device='';if(c.nBar===selected.id)c.nBar=''})}else if(selected.kind==='busbar')state.busbars=(state.busbars||[]).filter(b=>b.id!==selected.id);else state.wires=state.wires.filter(w=>w.id!==selected.id);selected=null;pending=null})}
const STATUS={partial:'niepełne zasilanie',unassigned:'—',nodata:'brak danych',unpowered:'bez zasilania',off:'wyłączony',short:'zwarcie'};
function renderBalance(t){const b=t.balance,max=Math.max(b.L1,b.L2,b.L3,1);$('phaseBalance').innerHTML=!t.supplied?'<span class="muted">Bilans faz: dodaj wyłącznik główny (FR) jako punkt zasilania.</span>':['L1','L2','L3'].map(l=>`<div class="phasebar"><b>${l}</b><span class="track"><span class="fill ${l}" style="width:${b[l]/max*100}%"></span></span><span>${(b[l]/1000).toLocaleString('pl-PL',{maximumFractionDigits:2})} kW</span></div>`).join('')+(b.unknown?`<div class="phasebar unknown"><b>?</b><span>${(b.unknown/1000).toLocaleString('pl-PL',{maximumFractionDigits:2})} kW bez ustalonej fazy</span></div>`:'')+'<p class="muted">Suma mocy zainstalowanej z listy obwodów, bez współczynnika jednoczesności. Kolory ekranowe: L3 czerwony dla czytelności – w instalacji żyła L3 jest szara (PN-HD 308).</p>'}
const f1=(v,d)=>v.toLocaleString('pl-PL',{maximumFractionDigits:d,minimumFractionDigits:d});
function calcCell(r){if(!r||(r.missing.length&&r.Iz==null&&r.dU==null))return '<span class="muted">brak danych</span>';const bad=r.issues.some(i=>i.severity==='error'),warn=r.issues.some(i=>i.severity==='warn');return `<span class="calc ${bad?'bad':warn?'warn':'ok'}">${r.Iz!=null?`Iz ${f1(r.Iz,1)} A${r.In!=null?(r.In<=r.Iz?' ≥ ':' < ')+'In '+f1(r.In,0)+' A':''}`:'Iz ?'}<br>${r.dU!=null?`ΔU ${f1(r.dU,2)}%${r.limit?` / ${r.limit}%`:''}`:'ΔU ?'}</span>`}
function renderCircuits(){const t=analyze(state),info=new Map(t.circuits.map(c=>[c.id,c])),calcBy=new Map(DINCalc.analyzeCircuits(state).results.map(r=>[r.id,r]));renderBalance(t);const nBars=state.components.filter(x=>isNBar(x.type));$('circuitCount').textContent=String(state.circuits.length);$('circuitRows').innerHTML=state.circuits.map(c=>{const ci=info.get(c.id),dev=state.components.find(x=>x.id===c.device),phase=ci?.phase?`${(ci.phases||[ci.phase]).map(p=>`<span class="phasechip ${p}">${p}</span>`).join(' ')}${ci.rcd.length?' <small>RCD</small>':''}`:esc(STATUS[ci?.status]||'—');return `<tr data-circuit="${c.id}"><td><input data-field="name" aria-label="Nazwa obwodu" value="${esc(c.name)}" maxlength="120"></td><td><select data-field="device" aria-label="Aparat obwodu"><option value="">Nie przypisano</option>${state.components.filter(x=>CIRCUIT_DEVICES.includes(x.type)).map(x=>`<option value="${x.id}" ${c.device===x.id?'selected':''}>${esc(x.label)}</option>`).join('')}</select></td><td class="phasecell">${phase}</td><td>${dev?.type==='RCBO'?'<span class="muted">własny N (RCBO)</span>':`<select data-field="nBar" aria-label="Listwa N obwodu"><option value="">Nie wskazano</option>${nBars.map(x=>`<option value="${x.id}" ${c.nBar===x.id?'selected':''}>${esc(x.label)}</option>`).join('')}</select>`}</td><td><input data-field="power" type="number" min="0" max="1000000" aria-label="Moc w watach" value="${c.power}"></td><td><input data-field="cable" aria-label="Opis przewodu" maxlength="60" value="${esc(c.cable)}"></td><td><input data-field="length" type="number" min="0" max="1000" step="1" aria-label="Długość obwodu w metrach" value="${c.length??''}"></td><td><select data-field="method" aria-label="Sposób ułożenia" title="${esc(DINCalc.METHODS[c.method]||'Sposób ułożenia wg PN-HD 60364-5-52')}"><option value="">?</option>${Object.keys(DINCalc.METHODS).map(k=>`<option value="${k}" ${c.method===k?'selected':''} title="${esc(DINCalc.METHODS[k])}">${k}</option>`).join('')}</select></td><td><select data-field="kind" aria-label="Rodzaj obwodu"><option value="">?</option>${Object.entries(DINCalc.KINDS).map(([k,v])=>`<option value="${k}" ${c.kind===k?'selected':''}>${v}</option>`).join('')}</select></td><td class="calccell">${calcCell(calcBy.get(c.id))}</td><td><button class="iconbtn" data-delete="${c.id}" title="Usuń obwód">×</button></td></tr>`}).join('')}
$('circuitRows').addEventListener('change',e=>{const id=e.target.closest('tr')?.dataset.circuit,field=e.target.dataset.field;if(!id||!field)return;const value=field==='power'?Math.max(0,Math.min(1000000,Number(e.target.value)||0)):field==='length'?(e.target.value===''?undefined:Math.max(0,Math.min(1000,Number(e.target.value)||0))):e.target.value;change(()=>state.circuits.find(c=>c.id===id)[field]=value)});
$('circuitRows').addEventListener('click',e=>{const id=e.target.dataset.delete;if(id)change(()=>state.circuits=state.circuits.filter(c=>c.id!==id))});
const plural=(n,one,few,many)=>n===1?one:(n%10>=2&&n%10<=4&&(n%100<12||n%100>14))?few:many;
function renderChecks(){if(!checked)return;const topo=analyze(state),issues=[...validate(state),...topo.issues,...DINCalc.analyzeCircuits(state).issues];const errors=issues.filter(i=>i.severity==='error').length,warns=issues.filter(i=>i.severity==='warn').length,infos=issues.filter(i=>i.free).length;const item=(i)=>`<button class="issueitem ${i.severity}" data-issue="${issues.indexOf(i)}"><strong>${esc(i.title)}</strong>${esc(i.text)}</button>`;$('checks').innerHTML=`<div class="checksummary ${errors?'has-errors':''}">${errors?'Wykryto '+errors+' '+plural(errors,'konflikt','konflikty','konfliktów')+' połączeń.':'Nie wykryto konfliktów w sprawdzanym zakresie.'}${warns?'<br>'+warns+' '+plural(warns,'uwaga','uwagi','uwag')+' do przejrzenia.':''}<br>Sprawdzono połączenia, fazy, zwarcia w modelu, grupy RCD, In ≤ Iz (Cu, PVC, 30 °C, bez współczynników) i spadek napięcia obwodów. Nie sprawdzono selektywności, prądów zwarciowych ani impedancji pętli.</div>`+issues.filter(i=>!i.free&&!i.calcMissing).map(item).join('')+(issues.some(i=>i.calcMissing)?`<details class="issuegroup"><summary>Brak danych do obliczeń: ${issues.filter(i=>i.calcMissing).length} ${plural(issues.filter(i=>i.calcMissing).length,'obwód','obwody','obwodów')}</summary>${issues.filter(i=>i.calcMissing).map(item).join('')}</details>`:'')+(infos?`<details class="issuegroup"><summary>Wolne zaciski: ${infos} ${plural(infos,'aparat','aparaty','aparatów')}</summary>${issues.filter(i=>i.free).map(item).join('')}</details>`:'');$('checks').querySelectorAll('[data-issue]').forEach(el=>el.onclick=()=>{const i=issues[+el.dataset.issue];selected=i.busbar&&!i.device?{kind:'busbar',id:i.busbar}:i.device?{kind:'device',id:i.device}:i.wire?{kind:'wire',id:i.wire}:null;render();if(i.device){const el=$('components').querySelector(`[data-id="${i.device}"]`);el?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})}})}
function setZoom(z){zoom=Math.round(Math.min(2,Math.max(.4,z))*100)/100;try{localStorage.setItem('din-zoom',String(zoom))}catch(e){}$('zoomReset').textContent=Math.round(zoom*100)+'%';$('zoomOut').disabled=zoom<=.4;$('zoomIn').disabled=zoom>=2;renderBoard()}
$('zoomIn').onclick=()=>setZoom(zoom+.1);$('zoomOut').onclick=()=>setZoom(zoom-.1);$('zoomReset').onclick=()=>setZoom(1);
$('zoomFit').onclick=()=>{const sc=document.querySelector('.boardscroll'),pad=parseFloat(getComputedStyle(sc).paddingLeft)+parseFloat(getComputedStyle(sc).paddingRight);setZoom(Math.floor((sc.clientWidth-pad-4)/(dims(state).modules*40+52)*100)/100)};
const PRESETS=[[1,12],[2,12],[3,12],[4,12],[2,18],[3,18],[4,18],[5,18],[4,24]];
let sizeMode='new';
function sizeInfo(){const r=+$('newRows').value,m=+$('newModules').value;if(!validDims(r,m)){$('sizeInfo').textContent=`Liczba szyn: ${LIMITS.rows[0]}–${LIMITS.rows[1]}, moduły na szynie: ${LIMITS.modules[0]}–${LIMITS.modules[1]}.`;$('sizeOk').disabled=true;return null}let msg=`Razem ${r*m} ${plural(r*m,'moduł','moduły','modułów')}.`;if(sizeMode==='resize'){const out=[...state.components.filter(c=>c.row>=r||c.slot+TYPES[c.type].width>m),...(state.busbars||[]).filter(b=>b.row>=r||b.to>=m).map(b=>({label:'szyna '+BUSBARS[b.type].short}))];if(out.length){$('sizeInfo').textContent=msg+` Nie zmieszczą się: ${out.map(c=>c.label).join(', ')}. Najpierw je przenieś lub usuń.`;$('sizeOk').disabled=true;return null}}$('sizeInfo').textContent=msg;$('sizeOk').disabled=false;$('presets').querySelectorAll('button').forEach(b=>b.classList.toggle('active',+b.dataset.r===r&&+b.dataset.m===m));return{r,m}}
function openSize(m){sizeMode=m;const d=dims(state);$('sizeTitle').textContent=m==='new'?'Nowa rozdzielnia':'Rozmiar obudowy';$('sizeLead').textContent=m==='new'?'Wybierz rozmiar obudowy: liczbę szyn DIN i liczbę modułów na każdej szynie. Obecny projekt zostaje zapisany na liście projektów.':'Zmień liczbę szyn lub modułów. Aparaty zostają na swoich miejscach, więc obudowę można zmniejszyć tylko do zajętych pozycji.';$('nameField').hidden=m!=='new';$('newName').value='Nowa rozdzielnia';$('newRows').value=m==='new'?4:d.rows;$('newModules').value=m==='new'?18:d.modules;$('sizeOk').textContent=m==='new'?'Utwórz':'Zastosuj';sizeInfo();$('sizeDialog').showModal()}
$('presets').innerHTML=PRESETS.map(([r,m])=>`<button type="button" data-r="${r}" data-m="${m}">${r} × ${m}</button>`).join('');
$('presets').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;$('newRows').value=b.dataset.r;$('newModules').value=b.dataset.m;sizeInfo()});
$('newRows').oninput=sizeInfo;$('newModules').oninput=sizeInfo;$('sizeCancel').onclick=()=>$('sizeDialog').close();
$('sizeForm').addEventListener('submit',e=>{e.preventDefault();const v=sizeInfo();if(!v)return;$('sizeDialog').close();if(sizeMode==='new'){const name=$('newName').value.trim().slice(0,120)||'Nowa rozdzielnia';if(!startProject(fresh(name,v.r,v.m)))return;toast(`Utworzono rozdzielnię ${v.r} × ${v.m} modułów.`)}else change(()=>{state.rows=v.r;state.modules=v.m});});
// Comb busbars are drawn over the terminal line of the chosen side; only the tag is clickable so terminals stay usable.
function busbarName(b){return `${BUSBARS[b.type].short} · rząd ${b.row+1} · moduły ${b.from+1}–${b.to+1}`}
function renderBusbars(){$('busbars').innerHTML=(state.busbars||[]).map(b=>{const y=67+b.row*137+(b.side==='t'?9:90),x=25+b.from*40,w=(b.to-b.from+1)*40-4,pins=underBusbar(state,b).inside.filter(c=>BUSBAR_DEVICES.includes(c.type));return `<div class="combbar ${b.type==='3P'?'three':''} ${selected?.kind==='busbar'&&selected.id===b.id?'selected':''}" style="left:${x}px;top:${y-3}px;width:${w}px">${pins.map(c=>`<i style="left:${c.slot*40+18-b.from*40}px" class="${b.type==='3P'?'p'+(c.slot-b.from)%3:''}"></i>`).join('')}<button class="bustag ${b.side==='t'?'up':'down'}" data-busbar="${b.id}" title="Szyna grzebieniowa ${esc(busbarName(b))}">SZ ${BUSBARS[b.type].short}</button></div>`}).join('')}
$('busbars').addEventListener('click',e=>{const id=e.target.closest('[data-busbar]')?.dataset.busbar;if(id){selected={kind:'busbar',id};render()}});
function runAround(c){const row=state.components.filter(x=>x.row===c.row&&BUSBAR_DEVICES.includes(x.type)).sort((a,b)=>a.slot-b.slot);let from=c.slot,to=c.slot+TYPES[c.type].width-1,grew=true;while(grew){grew=false;for(const x of row){if(x.slot+TYPES[x.type].width===from){from=x.slot;grew=true}if(x.slot===to+1){to=x.slot+TYPES[x.type].width-1;grew=true}}}return{from,to}}
function appendBusbarForm(c){const run=runAround(c),box=document.createElement('section');box.className='busform';box.innerHTML=`<h3>Szyna grzebieniowa</h3><p class="muted">Łączy zaciski L sąsiednich wyłączników jednym elementem zamiast osobnych przewodów. Domyślny zakres to ciągły rząd MCB/RCBO wokół ${esc(c.label)}.</p><div class="busgrid"><label class="field">Typ<select id="busType">${Object.entries(BUSBARS).map(([k,v])=>`<option value="${k}">${esc(v.name)}</option>`).join('')}</select></label><label class="field">Strona<select id="busSide"><option value="t">Górne zaciski</option><option value="b">Dolne zaciski</option></select></label><label class="field">Od modułu<input id="busFrom" type="number" min="1" max="${dims(state).modules}" value="${run.from+1}"></label><label class="field">Do modułu<input id="busTo" type="number" min="1" max="${dims(state).modules}" value="${run.to+1}"></label></div><button id="addBusbar">＋ Dodaj szynę</button>`;$('inspector').appendChild(box);$('addBusbar').onclick=()=>{const b={id:uid(),type:$('busType').value,side:$('busSide').value,row:c.row,from:+$('busFrom').value-1,to:+$('busTo').value-1};if(!Number.isInteger(b.from)||!Number.isInteger(b.to)||b.from<0||b.to<b.from||b.to>=dims(state).modules){toast('Nieprawidłowy zakres modułów.');return}if((state.busbars||[]).some(o=>o.row===b.row&&o.side===b.side&&o.from<=b.to&&b.from<=o.to)){toast('Po tej stronie rzędu jest już szyna w tym zakresie.');return}change(()=>{(state.busbars||(state.busbars=[])).push(b);selected={kind:'busbar',id:b.id}});toast('Dodano szynę grzebieniową. Doprowadź do niej zasilanie przewodem do jednego z wyłączników.')}}
function renderBusbarInspector(){const b=(state.busbars||[]).find(x=>x.id===selected.id);if(!b){selected=null;renderInspector();return}const devs=underBusbar(state,b).inside;$('inspector').innerHTML=`<h2>${esc(BUSBARS[b.type].name)}</h2><div class="kv"><span>Położenie</span><b>${esc(busbarName(b))}</b></div><div class="kv"><span>Strona</span><b>${b.side==='t'?'górne zaciski':'dolne zaciski'}</b></div><div class="kv"><span>Łączy</span><b>${devs.length?esc(devs.map(d=>d.label).join(', ')):'—'}</b></div><p class="muted" style="font-size:11px">${b.type==='3P'?'Piny powtarzają się co moduł: L1, L2, L3, L1… Faza każdego pinu wynika z tego, skąd szyna jest zasilana.':'Wszystkie wyłączniki pod szyną mają wspólny zacisk L.'} Model nie sprawdza obciążalności szyny.</p><button class="delete" id="deleteSelected">Usuń szynę</button>`;$('deleteSelected').onclick=removeSelected}
// Removing a rail deletes what sits on it and moves the rails below one row up.
function addRail(){const d=dims(state);if(d.rows>=LIMITS.rows[1]){toast(`Maksymalnie ${LIMITS.rows[1]} szyn.`);return}change(()=>{state.rows=d.rows+1;state.modules=d.modules});toast(`Dodano szynę ${d.rows+1}.`)}
function removeRail(i){const d=dims(state);if(d.rows<=1){toast('Rozdzielnia musi mieć co najmniej jedną szynę.');return}const gone=state.components.filter(c=>c.row===i),bars=(state.busbars||[]).filter(b=>b.row===i);if((gone.length||bars.length)&&!confirm(`Usunąć szynę ${i+1}${gone.length?` razem z ${gone.length} ${plural(gone.length,'aparatem','aparatami','aparatami')} i ich przewodami`:''}${bars.length?' oraz szynami grzebieniowymi':''}? Można to cofnąć.`))return;change(()=>{const ids=new Set(gone.map(c=>c.id));state.components=state.components.filter(c=>!ids.has(c.id));state.wires=state.wires.filter(w=>!ids.has(w.a.device)&&!ids.has(w.b.device));state.circuits.forEach(c=>{if(ids.has(c.device))c.device='';if(ids.has(c.nBar))c.nBar=''});state.busbars=(state.busbars||[]).filter(b=>b.row!==i);for(const c of state.components)if(c.row>i)c.row--;for(const b of state.busbars)if(b.row>i)b.row--;state.rows=d.rows-1;state.modules=d.modules;selected=null;pending=null});toast(`Usunięto szynę ${i+1}.`)}
$('rails').addEventListener('click',e=>{const b=e.target.closest('[data-rail]');if(b)removeRail(+b.dataset.rail)});$('addRail').onclick=addRail;$('print').onclick=()=>DINPrint.open(state);
// Circuit names under protective devices, like the label strip in a real board (also printed).
function labelCircuits(){const names=new Map();state.circuits.forEach((c,i)=>{if(c.device){if(!names.has(c.device))names.set(c.device,[]);names.get(c.device).push(`${i+1}. ${c.name}`)}});for(const[id,list]of names){const el=$('components').querySelector(`.device[data-id="${CSS.escape(id)}"]`);if(!el)continue;const tag=document.createElement('span');tag.className='circlabel';tag.textContent=list.join(' · ');tag.title=list.join(', ');el.appendChild(tag)}}
function openProjects(){const list=readIndex(),fmt=t=>new Date(t).toLocaleString('pl-PL',{dateStyle:'short',timeStyle:'short'});$('projectList').innerHTML=list.map(p=>`<li class="${p.id===projectId?'current':''}"><div><b>${esc(p.name)}</b><small>${p.id===projectId?'otwarty · ':''}zmiana ${fmt(p.updated)}</small></div><span><button type="button" data-open="${p.id}" ${p.id===projectId?'disabled':''}>Otwórz</button><button type="button" data-dup="${p.id}">Duplikuj</button><button type="button" class="danger" data-del="${p.id}" ${list.length<=1?'disabled':''}>Usuń</button></span></li>`).join('');$('projectsInfo').textContent=`${list.length} z ${MAX_PROJECTS} projektów. Zapis automatyczny po każdej zmianie, tylko w tej przeglądarce – na inny komputer przenieś projekt eksportem JSON.`;$('projectsDialog').showModal()}
$('projectList').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.open||b.dataset.dup||b.dataset.del;const p=loadProject(id);if(b.dataset.open){if(!p){toast('Nie udało się otworzyć projektu.');return}$('projectsDialog').close();openProjectState(id,p);toast('Otwarto: '+p.name)}else if(b.dataset.dup){if(!p)return;const copy={...p,name:(p.name+' (kopia)').slice(0,120)};if(startProject(copy)){$('projectsDialog').close();toast('Utworzono kopię projektu.')}}else if(b.dataset.del){const name=readIndex().find(x=>x.id===id)?.name||'projekt';if(!confirm(`Usunąć projekt „${name}”? Tego nie da się cofnąć (możesz wcześniej wyeksportować JSON).`))return;localStorage.removeItem(STORE.key(id));writeIndex(readIndex().filter(x=>x.id!==id));if(id===projectId){const next=readIndex()[0];openProjectState(next.id,loadProject(next.id)||fresh())}openProjects();toast('Usunięto projekt.')}});
$('projectsNew').onclick=()=>{$('projectsDialog').close();openSize('new')};$('projectsClose').onclick=()=>$('projectsDialog').close();
// Build version (written by scripts/version.mjs during the Vercel build; absent when served locally).
(()=>{const v=window.DIN_VERSION,el=$('buildInfo');if(!el)return;if(v&&v.sha){const t=new Date(v.time);el.textContent=`wersja ${v.sha.slice(0,7)} · ${isNaN(t)?v.time:t.toLocaleString('pl-PL',{dateStyle:'short',timeStyle:'short'})}`;el.title=`Commit ${v.sha}${v.message?' – '+v.message:''}`}else el.textContent='wersja lokalna (bez numeru commitu)'})();
// Strip size changes the device type (width and terminal count); block size is the number of holes per pole.
function appendSizeForm(c){const t=TYPES[c.type],box=document.createElement('section');box.className='busform';
 if(t.family){const fam=Object.entries(TYPES).filter(([,x])=>x.family===t.family);box.innerHTML=`<h3>Rozmiar listwy</h3><label class="field">Liczba zacisków<select id="stripSize">${fam.map(([k,x])=>`<option value="${k}" ${k===c.type?'selected':''}>${x.size} zacisków · ${x.width} mod.</option>`).join('')}</select></label>`;$('inspector').appendChild(box);
  $('stripSize').onchange=e=>{const nt=e.target.value;if(!fits(state,{...c,type:nt},c.row,c.slot)){toast('Większa listwa nie mieści się w tym miejscu. Zrób miejsce obok.');renderInspector();return}const keys=new Set(ports({...c,type:nt}).map(p=>p.key)),lost=state.wires.filter(w=>(w.a.device===c.id&&!keys.has(w.a.port))||(w.b.device===c.id&&!keys.has(w.b.port))).length;if(lost&&!confirm(`Mniejsza listwa ma mniej zacisków – zostanie usuniętych ${lost} przewodów. Kontynuować?`)){renderInspector();return}change(()=>{state.wires=state.wires.filter(w=>!((w.a.device===c.id&&!keys.has(w.a.port))||(w.b.device===c.id&&!keys.has(w.b.port))));c.type=nt;if(c.rating===t.rating)c.rating=TYPES[nt].rating})}}
 else{const poles=new Set(t.poles).size,cur=(c.rating.match(/×\s*(\d+)/)||[])[1];box.innerHTML=`<h3>Rozmiar bloku</h3><label class="field">Otwory na tor<select id="blockHoles">${HOLES.map(n=>`<option value="${n}" ${String(n)===cur?'selected':''}>${poles} × ${n}</option>`).join('')}</select></label><p class="muted" style="font-size:11px">Rysunek pokazuje po 4 punkty przyłączenia na tor; liczba otworów trafia do opisu i zestawienia materiałów.</p>`;$('inspector').appendChild(box);$('blockHoles').onchange=e=>change(()=>{c.rating=`${poles} × ${e.target.value} otworów`})}}
